/*
 * Noor Jahan Memorial offline application worker.
 * Build-time precache entries are generated by scripts/generate-sw-manifest.mjs.
 * Runtime caching is limited to same-origin app shell and static assets; no
 * patient records, local database content, or arbitrary API responses are cached.
 */
const CACHE_PREFIX = "noor-jahan-clinic-";
const CACHE_NAME = "noor-jahan-clinic-shell-v1";
const MANIFEST_FILE = "precache-manifest.json";

async function precacheApplicationShell() {
  const manifestUrl = new URL(MANIFEST_FILE, self.registration.scope);
  const manifestResponse = await fetch(manifestUrl, { cache: "no-store" });
  if (!manifestResponse.ok) throw new Error("Could not load the application precache manifest");
  const manifest = await manifestResponse.json();
  const urls = (manifest.assets || []).map((path) => new URL(path, self.registration.scope).href);
  urls.push(new URL("index.html", self.registration.scope).href);
  const cache = await caches.open(CACHE_NAME);
  await cache.addAll([...new Set(urls)]);
}

self.addEventListener("install", (event) => {
  event.waitUntil(precacheApplicationShell().then(() => self.skipWaiting()));
});

self.addEventListener("activate", (event) => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter((key) => key.startsWith(CACHE_PREFIX) && key !== CACHE_NAME).map((key) => caches.delete(key)));
    await self.clients.claim();
  })());
});

self.addEventListener("fetch", (event) => {
  const request = event.request;
  if (request.method !== "GET") return;
  const url = new URL(request.url);
  const scopeUrl = new URL(self.registration.scope);
  if (url.origin !== scopeUrl.origin || !url.pathname.startsWith(scopeUrl.pathname)) return;

  if (request.mode === "navigate") {
    event.respondWith((async () => {
      try {
        const response = await fetch(request);
        if (response.ok) return response;
      } catch { /* offline: serve the cached SPA shell below */ }
      const cache = await caches.open(CACHE_NAME);
      return (await cache.match(new URL("index.html", self.registration.scope).href)) || Response.error();
    })());
    return;
  }

  // Cache only build-time static resources. Empty-destination requests may be
  // data/JSON requests and are deliberately excluded for patient privacy.
  if (!["script", "style", "image", "font", "worker", "manifest"].includes(request.destination)) return;
  event.respondWith((async () => {
    const cache = await caches.open(CACHE_NAME);
    const cached = await cache.match(request);
    if (cached) return cached;
    try {
      const response = await fetch(request);
      if (response.ok && response.type === "basic") await cache.put(request, response.clone());
      return response;
    } catch {
      return Response.error();
    }
  })());
});
